import React, { Component } from "react";
import "../PagesCss/Aboutus.css";

export default class Aboutus extends Component {
    constructor(props) {
        super(props);
        this.state = {
            aboutus: null,
            error: null,
        };
    }

    componentDidMount() {
        fetch('http://localhost:3001/pages/1', { 
            method: 'POST',
        })
        .then(response => response.json())
        .then(page => {
            this.setState({ aboutus: page });
        })
        .catch(error => this.setState({ error: 'Error fetching data' }));
    }

    render() {
        const { aboutus, error } = this.state;
        if (error) return <div>{error}</div>;
        if (!aboutus) return <div>PAGE NOT FOUND</div>;

        let contentArray;
        try {
            contentArray = Array.isArray(aboutus.content) ? aboutus.content : JSON.parse(aboutus.content);
        } catch (e) {
            return <div>Invalid content format</div>;
        }

        return (
            <div className="about-containerr">
                <div className="about-rectangle">
                    <h1 className="TaiLink-About">{aboutus.title}</h1>
                    <div className="sen1">
                        {contentArray.map((item, index) => (
                            <p key={index}>
                                {item.p}
                            </p>
                        ))}
                    </div>
                </div>
            </div>
        );
    }
}
